  "prompt.tipo.guia_de_estudos.micro_3": "Kasten \"Beherrschungs-Checkliste\" mit 4 abhakbaren Punkten.",
  "prompt.tipo.guia_de_estudos.micro_4": "1 praktischer Lerntipp.",
  "prompt.tipo.guia_de_estudos.restricao": "Füge KEINEN Lösungsschlüssel und keine ausführlich gelösten Übungen ein.",
  "prompt.tipo.guia_do_professor.apoio": "Lehrerhandreichung",
  "prompt.tipo.guia_do_professor.foco": "die Lehrkraft dabei unterstützen, den Unterricht zum Thema zu leiten",
  "prompt.tipo.guia_do_professor.micro_1": "Unterrichtsziele in 2 bis 3 Stichpunkten.",
  "prompt.tipo.guia_do_professor.micro_2": "Unterrichtsablauf in 3 bis 4 nummerierten Phasen, mit empfohlener Zeit.",
  "prompt.tipo.guia_do_professor.micro_3": "Kasten \"Erwartete Schwierigkeiten\" mit 2 bis 3 Punkten.",
  "prompt.tipo.guia_do_professor.micro_4": "Kasten \"Einstiegsfrage\" mit 1 Frage zum Beginn des Unterrichts.",
  "prompt.tipo.guia_do_professor.restricao": "Sprache, die sich an die Lehrkraft richtet, nicht an die Schüler/innen.",
  "prompt.tipo.mapa_mental.apoio": "Mindmap",
  "prompt.tipo.mapa_mental.foco": "die Beziehungen zwischen den Konzepten des Themas zeigen",
  "prompt.tipo.mapa_mental.micro_1": "Zentraler Knoten: das Thema in Großbuchstaben.",
  "prompt.tipo.mapa_mental.micro_2": "Hauptäste: die großen Konzepte des Themas, in Schlüsselwörtern.",
  "prompt.tipo.mapa_mental.micro_3": "Unteräste: Definitionen, Formeln, Beispiele und Beziehungen, in Sätzen mit höchstens 5 Wörtern.",
  "prompt.tipo.mapa_mental.restricao": "Füge KEINE Aufgaben, Übungen, Lösungen, Absätze oder Fließtext ein. Erzeuge KEIN Layout in Spalten, wie ein Arbeitsheft oder eine Infografik: nur eine Mindmap.",
  "prompt.tipo.material_complementar.apoio": "Ergänzungsmaterial",
  "prompt.tipo.material_complementar.foco": "das Thema mit Wissenswertem, Anwendungen und Kontext über den Grundinhalt hinaus erweitern",
  "prompt.tipo.material_complementar.micro_1": "Anregende Einstiegsfrage.",
  "prompt.tipo.material_complementar.micro_2": "Kurzer Zusammenfassungstext (2 bis 3 Sätze), der den Inhalt erweitert.",
  "prompt.tipo.material_complementar.micro_3": "Kasten \"Wusstest du schon?\" mit 2 korrekten und überprüfbaren Fakten.",
  "prompt.tipo.material_complementar.micro_4": "Kasten \"Im echten Leben\" mit 1 praktischen Anwendung.",
  "prompt.tipo.material_complementar.micro_5": "Kasten \"Zum Weiterdenken\" mit 2 Vertiefungsvorschlägen, ohne bestimmte Websites, Bücher oder Autoren zu nennen.",
  "prompt.tipo.material_complementar.restricao": "Erfinde KEINE Kuriositäten, Daten, Quellen oder Zahlen: Verwende nur allgemein bekannte und korrekte Fakten.",
  "prompt.tipo.material_de_revisao.apoio": "Schnelle Wiederholung",
  "prompt.tipo.material_de_revisao.foco": "das Wesentliche des bereits Gelernten wiederholen und häufige Fehler hervorheben",
  "prompt.tipo.material_de_revisao.micro_1": "1 Einstiegssatz, der sagt, was wiederholt wird.",
  "prompt.tipo.material_de_revisao.micro_2": "6 Stichpunkte mit ✓ mit den wesentlichen Punkten.",
  "prompt.tipo.material_de_revisao.micro_3": "Kasten \"Häufige Fehler\" mit 3 kurzen Punkten.",
  "prompt.tipo.material_de_revisao.micro_4": "Kasten \"Merke\" mit der wichtigsten Regel oder Formel.",
  "prompt.tipo.material_de_revisao.restricao": "Führe KEINEN neuen Inhalt ein: Wiederhole nur das Wesentliche des Themas.",
  "prompt.tipo.material_para_concurso.apoio": "Vorbereitung auf Auswahlprüfungen",
  "prompt.tipo.material_para_concurso.foco": "das in Prüfungen am häufigsten Abgefragte verdichten, mit Fallstricken und Eselsbrücken",
  "prompt.tipo.material_para_concurso.micro_1": "Kasten \"Wie es meist abgefragt wird\" mit 2 bis 3 Punkten.",
  "prompt.tipo.material_para_concurso.micro_2": "5 Stichpunkte mit den wichtigsten Punkten.",
  "prompt.tipo.material_para_concurso.micro_3": "Kasten \"Fallstricke\" mit 3 Punkten.",
  "prompt.tipo.material_para_concurso.micro_4": "1 Eselsbrücke oder Merkhilfe, nur wenn sie allgemein bekannt und korrekt ist.",
  "prompt.tipo.material_para_concurso.restricao": "Erfinde KEINE Statistiken von Prüfungsinstitutionen und nenne keine echten Fragen oder Prüfungsinstitutionen.",
  "prompt.tipo.material_preparatorio.apoio": "Vorbereitungsmaterial",
  "prompt.tipo.material_preparatorio.foco": "auf eine Prüfung oder Stufe vorbereiten, mit dem Wesentlichen und dem, was zu üben ist",
  "prompt.tipo.material_preparatorio.micro_1": "Ziel der Vorbereitung in 1 Satz.",
  "prompt.tipo.material_preparatorio.micro_2": "Übersicht der am häufigsten abgefragten Inhalte: 4 bis 6 Themen in Prioritätsreihenfolge.",
  "prompt.tipo.material_preparatorio.micro_3": "Kasten \"Wie lernen\" mit 3 Schritten.",
  "prompt.tipo.material_preparatorio.micro_4": "Kasten \"Achtung\" mit 3 häufigen Fehlern.",
  "prompt.tipo.material_preparatorio.micro_5": "Mini-Checkliste zur Beherrschung mit 4 abhakbaren Punkten.",
  "prompt.tipo.material_preparatorio.restricao": "Füge KEINE ausführlich gelösten Fragen und keinen Lösungsschlüssel ein; nenne, was zu üben ist. Erfinde KEINE Prüfungsstatistiken.",
  "prompt.tipo.material_profissional.apoio": "Berufsmaterial",
  "prompt.tipo.material_profissional.foco": "das Thema auf die Arbeitspraxis anwenden, mit Verfahren und Sicherheit",
  "prompt.tipo.material_profissional.micro_1": "Beruflicher Anwendungskontext in 1 bis 2 Sätzen.",
  "prompt.tipo.material_profissional.micro_2": "Verfahren in 4 bis 6 nummerierten Schritten.",
  "prompt.tipo.material_profissional.micro_3": "Kasten \"Achtung / Sicherheit\" mit den wesentlichen Vorsichtsmaßnahmen.",
  "prompt.tipo.material_profissional.micro_4": "Kasten \"In der Praxis\" mit 1 realen Arbeitssituation.",
  "prompt.tipo.material_profissional.restricao": "Nenne technische Normen nur mit korrekter Nummer und korrektem Inhalt; bei Zweifeln schreibe \"Gültige Norm konsultieren\".",
